import{_ as t,a as o,o as r,a4 as d}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"Products","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-products","title":"List Products","description":"Default paginated list — no filters, default sort, page 1, 30 items.","request":"curl -X GET \\"http://localhost/api/shop/products\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 84\\nX-Page: 1\\nX-Per-Page: 30\\nX-Total-Pages: 3\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n    \\"type\\": \\"simple\\",\\n    \\"bookingType\\": null,\\n    \\"name\\": \\"Coastal Breeze Men\'s Blue Zipper Hoodie\\",\\n    \\"urlKey\\": \\"coastal-breeze-mens-blue-zipper-hoodie\\",\\n    \\"status\\": true,\\n    \\"shortDescription\\": \\"Stay warm and stylish…\\",\\n    \\"price\\": 100,\\n    \\"specialPrice\\": null,\\n    \\"new\\": true,\\n    \\"featured\\": true,\\n    \\"minimumPrice\\": 100,\\n    \\"maximumPrice\\": 100,\\n    \\"formattedPrice\\": \\"$100.00\\",\\n    \\"formattedSpecialPrice\\": null,\\n    \\"formattedMinimumPrice\\": \\"$100.00\\",\\n    \\"formattedMaximumPrice\\": \\"$100.00\\",\\n    \\"baseImageUrl\\": \\"http://localhost/storage/product/1/zKcWZTLDjcawJmaNg8g1cpARqwVONgEKEflabstT.webp\\",\\n    \\"isInWishlist\\": 0,\\n    \\"isInCompare\\": 0\\n  }\\n]\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Missing or invalid `X-STOREFRONT-KEY`","solution":"Send a valid storefront API key."},{"error":"403 Forbidden","cause":"Storefront key inactive or rate-limited","solution":"Activate the key or wait for the rate limit window to reset."}]},{"id":"list-products-wishlist-compare-flags","title":"List Products with Wishlist & Compare Flags","description":"Every card carries `isInWishlist` and `isInCompare` so you can highlight the wishlist / compare icon directly from the listing — no need to separately fetch and cross-reference the wishlist or compare lists. These are per-customer flags (`1` = in the list, `0` = not), so include the customer Bearer token; without it (guest) both are always `0`.","request":"curl -X GET \\"http://localhost/api/shop/products?per_page=3\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\" \\\\\\n  -H \\"Authorization: Bearer 1|customer_token_xxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 84\\nX-Page: 1\\nX-Per-Page: 3\\nX-Total-Pages: 28\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n    \\"type\\": \\"simple\\",\\n    \\"name\\": \\"Coastal Breeze Men\'s Blue Zipper Hoodie\\",\\n    \\"price\\": 100,\\n    \\"baseImageUrl\\": \\"http://localhost/storage/product/1/zKcWZTLDjcawJmaNg8g1cpARqwVONgEKEflabstT.webp\\",\\n    \\"isInWishlist\\": 1,\\n    \\"isInCompare\\": 0\\n  },\\n  {\\n    \\"id\\": 22,\\n    \\"sku\\": \\"ACME-DRAWBAG-001\\",\\n    \\"type\\": \\"simple\\",\\n    \\"name\\": \\"Acme Drawstring Bag\\",\\n    \\"price\\": 3000,\\n    \\"baseImageUrl\\": \\"http://localhost/storage/product/22/acme-drawbag.webp\\",\\n    \\"isInWishlist\\": 0,\\n    \\"isInCompare\\": 1\\n  },\\n  {\\n    \\"id\\": 92,\\n    \\"sku\\": \\"bagisto-sticker\\",\\n    \\"type\\": \\"simple\\",\\n    \\"name\\": \\"Bagisto Sticker\\",\\n    \\"price\\": 10,\\n    \\"baseImageUrl\\": \\"http://localhost/storage/product/92/sticker.webp\\",\\n    \\"isInWishlist\\": 0,\\n    \\"isInCompare\\": 0\\n  }\\n]\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Missing or invalid `X-STOREFRONT-KEY`","solution":"Send a valid storefront API key."}]},{"id":"paginated-products","title":"Paginated List","description":"Use `page` and `per_page` to walk the full catalog. Pagination metadata is always emitted as headers.","request":"curl -X GET \\"http://localhost/api/shop/products?page=2&per_page=20\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 84\\nX-Page: 2\\nX-Per-Page: 20\\nX-Total-Pages: 5\\n\\n[\\n  { \\"id\\": 21, \\"sku\\": \\"...\\", \\"type\\": \\"simple\\", \\"name\\": \\"...\\", \\"price\\": 49, \\"...\\": \\"...\\" },\\n  { \\"id\\": 22, \\"sku\\": \\"...\\", \\"type\\": \\"simple\\", \\"name\\": \\"...\\", \\"price\\": 89, \\"...\\": \\"...\\" }\\n]\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Missing or invalid `X-STOREFRONT-KEY`","solution":"Send a valid storefront API key."}]}]},"headers":[],"relativePath":"api/rest-api/shop/products/get-products.md","filePath":"api/rest-api/shop/products/get-products.md","lastUpdated":1783079210000}'),a={name:"api/rest-api/shop/products/get-products.md"};function s(i,e,c,n,l,p){return r(),o("div",null,e[0]||(e[0]=[d('<h1 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h1><p>Paginated list of catalog products. The response is a <strong>slim card-level payload</strong> — fields needed to render listing/grid/search results. For the full PDP shape (categories, variants, bundle options, booking config, customizable options, related products, …) use <a href="/api/rest-api/shop/products/get-product.html">Single Product</a>.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/products</span></span></code></pre></div><p>This same endpoint also powers all filtering, sorting and search — see <a href="/api/rest-api/shop/products/search-product.html">Search Products</a> for the full set of query parameters.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Accept</code></td><td>Yes</td><td><code>application/json</code></td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Storefront API key (<code>pk_storefront_…</code>)</td></tr><tr><td><code>X-Locale</code></td><td>No</td><td>Override request locale</td></tr><tr><td><code>X-Channel</code></td><td>No</td><td>Override channel scope</td></tr><tr><td><code>X-Currency</code></td><td>No</td><td>Override currency in <code>formattedPrice</code> etc.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>integer</td><td>1</td><td>Page number (1-based)</td></tr><tr><td><code>per_page</code></td><td>integer</td><td>30</td><td>Items per page. Capped at 50.</td></tr></tbody></table><p>For all filter / search / sort parameters (<code>query</code>, <code>sort</code>, <code>type</code>, <code>category_id</code>, <code>price</code>, attribute filters …) see <a href="/api/rest-api/shop/products/search-product.html">Search Products</a>.</p><p>Pagination headers (<code>X-Total-Count</code>, <code>X-Page</code>, <code>X-Per-Page</code>, <code>X-Total-Pages</code>) are always emitted — see <a href="/api/rest-api/introduction.html#pagination">Pagination</a>.</p><h2 id="card-level-fields" tabindex="-1">Card-level fields <a class="header-anchor" href="#card-level-fields" aria-label="Permalink to &quot;Card-level fields&quot;">​</a></h2><p>These ~20 fields are returned for every product in the list. The PDP endpoint returns these <strong>plus</strong> every related resource inlined.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Product primary key</td></tr><tr><td><code>sku</code></td><td>string</td><td>Stock-keeping unit</td></tr><tr><td><code>type</code></td><td>string</td><td><code>simple</code>, <code>configurable</code>, <code>bundle</code>, <code>grouped</code>, <code>virtual</code>, <code>downloadable</code>, <code>booking</code></td></tr><tr><td><code>bookingType</code></td><td>string | null</td><td>When <code>type = booking</code>: <code>default</code>, <code>appointment</code>, <code>rental</code>, <code>event</code>, <code>table</code> — otherwise <code>null</code></td></tr><tr><td><code>name</code></td><td>string</td><td>Localized name</td></tr><tr><td><code>urlKey</code></td><td>string</td><td>URL slug</td></tr><tr><td><code>status</code></td><td>boolean</td><td>Whether the product is published</td></tr><tr><td><code>shortDescription</code></td><td>string</td><td>Short marketing description</td></tr><tr><td><code>price</code></td><td>number</td><td>Default price</td></tr><tr><td><code>specialPrice</code></td><td>number | null</td><td>Sale price when in promotion window</td></tr><tr><td><code>new</code></td><td>boolean</td><td>&quot;New&quot; flag set in admin</td></tr><tr><td><code>featured</code></td><td>boolean</td><td>&quot;Featured&quot; flag set in admin</td></tr><tr><td><code>minimumPrice</code></td><td>number</td><td>Lowest price across variants (configurable / bundle)</td></tr><tr><td><code>maximumPrice</code></td><td>number</td><td>Highest price across variants</td></tr><tr><td><code>formattedPrice</code></td><td>string</td><td>Currency-formatted <code>price</code></td></tr><tr><td><code>formattedSpecialPrice</code></td><td>string | null</td><td>Currency-formatted <code>specialPrice</code></td></tr><tr><td><code>formattedMinimumPrice</code></td><td>string</td><td>Currency-formatted <code>minimumPrice</code></td></tr><tr><td><code>formattedMaximumPrice</code></td><td>string</td><td>Currency-formatted <code>maximumPrice</code></td></tr><tr><td><code>baseImageUrl</code></td><td>string | null</td><td>Primary thumbnail URL</td></tr><tr><td><code>isInWishlist</code></td><td>integer (0/1)</td><td><code>1</code> if this product is in the signed-in customer&#39;s wishlist (active channel), else <code>0</code>. <code>0</code> for guests.</td></tr><tr><td><code>isInCompare</code></td><td>integer (0/1)</td><td><code>1</code> if this product is in the signed-in customer&#39;s compare list, else <code>0</code>. <code>0</code> for guests.</td></tr></tbody></table><blockquote><p>Heavy relations (<code>images</code>, <code>videos</code>, <code>categories</code>, <code>channels</code>, <code>variants</code>, <code>bookingProducts</code>, <code>bundleOptions</code>, <code>customizableOptions</code>, <code>relatedProducts</code>, etc.) are <strong>omitted</strong> from the list response. Fetch the <a href="/api/rest-api/shop/products/get-product.html">Single Product</a> to get them inlined.</p></blockquote><h2 id="wishlist-compare-flags" tabindex="-1">Wishlist &amp; compare flags <a class="header-anchor" href="#wishlist-compare-flags" aria-label="Permalink to &quot;Wishlist &amp; compare flags&quot;">​</a></h2><p>Every product card carries two per-customer booleans, <code>isInWishlist</code> and <code>isInCompare</code>, so you can render the wishlist and compare icon states straight from the listing response.</p><p>Why they exist: the wishlist and compare lists are their own endpoints and paginate independently of the catalog — a product on catalog page 1 may have its wishlist entry on a different wishlist page, so matching the two lists on the client is unreliable. These flags answer the question per product, in the same response, so the wishlist/compare icon can be highlighted without any extra requests.</p><ul><li><strong>Authentication is required.</strong> Include the customer Bearer token alongside the storefront key. For guests (no customer token) both flags are always <code>0</code>.</li><li><strong><code>isInWishlist</code></strong> is scoped to the active channel; <strong><code>isInCompare</code></strong> applies across the store.</li><li>A product is flagged (<code>1</code>) when its own product ID is in the customer&#39;s wishlist / compare list — so a configurable parent is flagged when the parent itself was added.</li><li>The REST API returns these as <code>1</code> / <code>0</code> integers. (Over GraphQL the same flags are returned as the strings <code>&quot;1&quot;</code> / <code>&quot;0&quot;</code>.)</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li>Render a category page / grid view / search results with paginated cards.</li><li>Implement infinite scroll using <code>?page=N&amp;per_page=20</code> and <code>X-Total-Pages</code>.</li><li>Pre-load the next page based on <code>X-Page &lt; X-Total-Pages</code>.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/products/get-product.html">Single Product</a> — full PDP-ready document with every relation embedded</li><li><a href="/api/rest-api/shop/products/search-product.html">Search Products</a> — full filter / sort / search reference</li><li><a href="/api/rest-api/shop/products/get-booking-slots.html">Booking Slots</a> — runtime availability for <code>booking</code> products</li><li><a href="/api/rest-api/shop/categories/get-categories.html">Categories</a> — <code>?category_id=N</code> to scope by category</li><li><a href="/api/rest-api/shop/attributes/get-attributes.html">Attributes</a> — discover filterable attribute codes</li></ul>',23)]))}const g=t(a,[["render",s]]);export{h as __pageData,g as default};
